export interface Team {
  id: string;
  name: string;
  score: number;
}

export enum GameStage {
  SETUP = 'SETUP',
  SCENARIO = 'SCENARIO',
  JUDGING = 'JUDGING',
  WINNER = 'WINNER'
}

export interface GameState {
  stage: GameStage;
  teams: Team[];
  currentScenario: string | null;
  history: string[]; // Keep track of past scenarios to avoid dupes if we wanted complexity
  roundNumber: number;
  totalRounds: number;
}

export interface ScenarioResponse {
  scenario: string;
  category?: string;
}

import React, { useState } from 'react';
import { v4 as uuidv4 } from 'uuid';
import { Team, GameState, GameStage } from './types';
import { SetupScreen } from './components/SetupScreen';
import { GameScreen } from './components/GameScreen';
import { ScoringScreen } from './components/ScoringScreen';
import { WinnerScreen } from './components/WinnerScreen';

const App: React.FC = () => {
  const [gameState, setGameState] = useState<GameState>({
    stage: GameStage.SETUP,
    teams: [],
    currentScenario: null,
    history: [],
    roundNumber: 1,
    totalRounds: 5
  });

  const handleSetupComplete = (teams: Team[], rounds: number) => {
    setGameState(prev => ({
      ...prev,
      teams: teams,
      totalRounds: rounds,
      stage: GameStage.SCENARIO,
      roundNumber: 1,
      currentScenario: null
    }));
  };

  const setScenario = (scenario: string) => {
    setGameState(prev => ({
      ...prev,
      currentScenario: scenario,
      history: [...prev.history, scenario]
    }));
  };

  const finishRound = () => {
    setGameState(prev => ({
      ...prev,
      stage: GameStage.JUDGING
    }));
  };

  const updateScore = (teamId: string, points: number) => {
    setGameState(prev => ({
      ...prev,
      teams: prev.teams.map(t => 
        t.id === teamId ? { ...t, score: t.score + points } : t
      )
    }));
  };

  const nextRound = () => {
    if (gameState.roundNumber >= gameState.totalRounds) {
      endGame();
    } else {
      setGameState(prev => ({
        ...prev,
        stage: GameStage.SCENARIO,
        currentScenario: null,
        roundNumber: prev.roundNumber + 1
      }));
    }
  };

  const endGame = () => {
    setGameState(prev => ({
      ...prev,
      stage: GameStage.WINNER
    }));
  };

  const restartGame = () => {
    setGameState({
      stage: GameStage.SETUP,
      teams: [],
      currentScenario: null,
      history: [],
      roundNumber: 1,
      totalRounds: 5
    });
  };

  // Simple render switch
  const renderStage = () => {
    switch (gameState.stage) {
      case GameStage.SETUP:
        return (
          <SetupScreen 
            onSetupComplete={handleSetupComplete}
          />
        );
      case GameStage.SCENARIO:
        return (
          <GameScreen 
            scenario={gameState.currentScenario}
            setScenario={setScenario}
            onFinished={finishRound}
            roundNumber={gameState.roundNumber}
            totalRounds={gameState.totalRounds}
          />
        );
      case GameStage.JUDGING:
        return (
          <ScoringScreen 
            teams={gameState.teams}
            onUpdateScore={updateScore}
            onNextRound={nextRound}
            onEndGame={endGame}
            roundNumber={gameState.roundNumber}
          />
        );
      case GameStage.WINNER:
        return (
          <WinnerScreen 
            teams={gameState.teams}
            onRestart={restartGame}
          />
        );
      default:
        return null;
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 text-slate-900 font-sans selection:bg-indigo-100 selection:text-indigo-700">
      {/* Background decoration */}
      <div className="fixed inset-0 z-0 overflow-hidden pointer-events-none">
        <div className="absolute -top-40 -right-40 w-96 h-96 bg-secondary/10 rounded-full blur-3xl"></div>
        <div className="absolute top-1/2 -left-20 w-72 h-72 bg-primary/10 rounded-full blur-3xl"></div>
        <div className="absolute bottom-0 right-1/3 w-80 h-80 bg-accent/10 rounded-full blur-3xl"></div>
      </div>

      {/* Main Content */}
      <main className="relative z-10 min-h-screen flex flex-col">
        {renderStage()}
      </main>
    </div>
  );
};

export default App;

