import React, { useEffect, useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Clock, RefreshCw, CheckCircle } from 'lucide-react';
import { Button } from './Button';
import { generateScenario } from '../services/geminiService';

interface GameScreenProps {
  scenario: string | null;
  setScenario: (scenario: string) => void;
  onFinished: () => void;
  roundNumber: number;
  totalRounds: number;
}

export const GameScreen: React.FC<GameScreenProps> = ({ 
  scenario, 
  setScenario, 
  onFinished, 
  roundNumber,
  totalRounds
}) => {
  const [loading, setLoading] = useState(false);
  const [timeLeft, setTimeLeft] = useState<number | null>(null);

  const fetchScenario = async () => {
    setLoading(true);
    const newScenario = await generateScenario();
    setScenario(newScenario);
    setLoading(false);
    // Reset timer
    setTimeLeft(null); 
  };

  useEffect(() => {
    if (!scenario) {
      fetchScenario();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useEffect(() => {
    if (timeLeft === null || timeLeft <= 0) return;
    const timer = setInterval(() => {
      setTimeLeft(prev => (prev !== null ? prev - 1 : null));
    }, 1000);
    return () => clearInterval(timer);
  }, [timeLeft]);

  const startTimer = (seconds: number) => {
    setTimeLeft(seconds);
  };

  return (
    <div className="flex flex-col items-center justify-center h-full w-full max-w-4xl mx-auto px-6 py-8">

      {/* Header Info */}
      <div className="w-full flex justify-between items-center mb-8 md:mb-12">
        <div className="flex items-center gap-2 text-slate-500 font-display font-semibold">
          <span className="bg-indigo-100 text-primary px-4 py-1 rounded-full text-sm">Sæt Scenen!</span>
        </div>
        <div className="text-slate-400 font-bold">
          Scene {roundNumber} af {totalRounds}
        </div>
      </div>

      {/* Main Content Area */}
      <div className="flex-grow flex flex-col items-center justify-center w-full mb-12 relative min-h-[400px]">
        <AnimatePresence mode="wait">
          {loading ? (
            <motion.div
              key="loader"
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              className="flex flex-col items-center"
            >
              <div className="w-20 h-20 border-8 border-indigo-100 border-t-primary rounded-full animate-spin mb-8"></div>
              <h2 className="text-3xl font-display font-bold text-slate-700 animate-pulse">
                Finder på noget sjovt...
              </h2>
            </motion.div>
          ) : (
            <motion.div
              key="scenario"
              initial={{ opacity: 0, scale: 0.8, y: 20 }}
              animate={{ opacity: 1, scale: 1, y: 0 }}
              exit={{ opacity: 0, scale: 1.1 }}
              className="w-full text-center"
            >
              <div className="text-lg font-bold text-indigo-500 tracking-widest uppercase mb-6">
                Jeres opgave er:
              </div>
              <h1 className="text-5xl md:text-7xl font-display font-black text-slate-800 leading-tight mb-12 drop-shadow-sm">
                "{scenario}"
              </h1>

              {/* Timer Display */}
              {timeLeft !== null && timeLeft > 0 && (
                <motion.div 
                  initial={{ scale: 0 }}
                  animate={{ scale: 1 }}
                  className="text-9xl font-black text-secondary mb-8 tabular-nums"
                >
                  {timeLeft}
                </motion.div>
              )}

              {timeLeft === 0 && (
                 <motion.div 
                 initial={{ scale: 0.5, opacity: 0 }}
                 animate={{ scale: 1, opacity: 1 }}
                 className="text-8xl font-black text-red-500 mb-8 uppercase"
               >
                 FRYS!
               </motion.div>
              )}
            </motion.div>
          )}
        </AnimatePresence>
      </div>

      {/* Controls */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4 w-full max-w-2xl">
        <Button 
          variant="ghost" 
          onClick={fetchScenario} 
          disabled={loading || (timeLeft !== null && timeLeft > 0)}
          className="w-full"
        >
          <RefreshCw className="w-5 h-5" />
          Nyt Scenarie
        </Button>

        <Button 
          variant="secondary" 
          size="lg"
          onClick={() => startTimer(15)} 
          disabled={loading || (timeLeft !== null && timeLeft > 0)}
          className="w-full shadow-lg"
        >
          <Clock className="w-6 h-6" />
          15 Sekunder
        </Button>

        <Button 
          variant="primary" 
          size="lg"
          onClick={onFinished} 
          disabled={loading}
          className="w-full shadow-lg"
        >
          <CheckCircle className="w-6 h-6" />
          Bedøm Hold
        </Button>
      </div>
    </div>
  );
};

import React from 'react';
import { motion } from 'framer-motion';

interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: 'primary' | 'secondary' | 'accent' | 'danger' | 'ghost' | 'success';
  size?: 'sm' | 'md' | 'lg' | 'xl';
  isLoading?: boolean;
  wiggle?: boolean;
}

export const Button: React.FC<ButtonProps> = ({ 
  children, 
  variant = 'primary', 
  size = 'md', 
  className = '', 
  isLoading = false,
  wiggle = false,
  disabled,
  ...props 
}) => {

  // Base style: Thick borders, hard shadow (pop), rounded-xl
  const baseStyle = "font-display font-black rounded-xl border-4 border-black transition-all duration-100 flex items-center justify-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed disabled:shadow-none active:translate-x-[4px] active:translate-y-[4px] active:shadow-pop-active";

  // Variants with bright colors
  const variants = {
    primary: "bg-[#8b5cf6] text-white shadow-pop hover:bg-[#7c3aed]",
    secondary: "bg-[#f472b6] text-white shadow-pop hover:bg-[#ec4899]",
    accent: "bg-[#fbbf24] text-black shadow-pop hover:bg-[#f59e0b]",
    success: "bg-[#a3e635] text-black shadow-pop hover:bg-[#84cc16]",
    danger: "bg-[#ef4444] text-white shadow-pop hover:bg-[#dc2626]",
    ghost: "bg-white text-black shadow-pop hover:bg-slate-50 border-black",
  };

  const sizes = {
    sm: "px-4 py-2 text-sm",
    md: "px-6 py-3 text-lg",
    lg: "px-8 py-4 text-xl",
    xl: "px-10 py-6 text-2xl tracking-wide",
  };

  return (
    <motion.button
      whileHover={{ scale: disabled || isLoading ? 1 : 1.05, rotate: disabled ? 0 : -2 }}
      whileTap={{ scale: 0.95, rotate: 0 }}
      animate={wiggle ? { rotate: [0, -3, 3, -3, 3, 0], transition: { repeat: Infinity, duration: 2 } } : {}}
      className={`${baseStyle} ${variants[variant]} ${sizes[size]} ${className}`}
      disabled={disabled || isLoading}
      {...props}
    >
      {isLoading ? (
        <>
          <div className="w-6 h-6 border-4 border-black border-t-transparent rounded-full animate-spin mr-2"></div>
          Vent...
        </>
      ) : children}
    </motion.button>
  );
};

import React, { useState } from 'react';
import { v4 as uuidv4 } from 'uuid';
import { Team, GameState, GameStage } from './types';
import { SetupScreen } from './components/SetupScreen';
import { GameScreen } from './components/GameScreen';
import { ScoringScreen } from './components/ScoringScreen';
import { WinnerScreen } from './components/WinnerScreen';

const App: React.FC = () => {
  const [gameState, setGameState] = useState<GameState>({
    stage: GameStage.SETUP,
    teams: [],
    currentScenario: null,
    history: [],
    roundNumber: 1,
    totalRounds: 5
  });

  const handleSetupComplete = (teams: Team[], rounds: number) => {
    setGameState(prev => ({
      ...prev,
      teams: teams,
      totalRounds: rounds,
      stage: GameStage.SCENARIO,
      roundNumber: 1,
      currentScenario: null
    }));
  };

  const setScenario = (scenario: string) => {
    setGameState(prev => ({
      ...prev,
      currentScenario: scenario,
      history: [...prev.history, scenario]
    }));
  };

  const finishRound = () => {
    setGameState(prev => ({
      ...prev,
      stage: GameStage.JUDGING
    }));
  };

  const updateScore = (teamId: string, points: number) => {
    setGameState(prev => ({
      ...prev,
      teams: prev.teams.map(t => 
        t.id === teamId ? { ...t, score: t.score + points } : t
      )
    }));
  };

  const nextRound = () => {
    if (gameState.roundNumber >= gameState.totalRounds) {
      endGame();
    } else {
      setGameState(prev => ({
        ...prev,
        stage: GameStage.SCENARIO,
        currentScenario: null,
        roundNumber: prev.roundNumber + 1
      }));
    }
  };

  const endGame = () => {
    setGameState(prev => ({
      ...prev,
      stage: GameStage.WINNER
    }));
  };

  const restartGame = () => {
    setGameState({
      stage: GameStage.SETUP,
      teams: [],
      currentScenario: null,
      history: [],
      roundNumber: 1,
      totalRounds: 5
    });
  };

  // Simple render switch
  const renderStage = () => {
    switch (gameState.stage) {
      case GameStage.SETUP:
        return (
          <SetupScreen 
            onSetupComplete={handleSetupComplete}
          />
        );
      case GameStage.SCENARIO:
        return (
          <GameScreen 
            scenario={gameState.currentScenario}
            setScenario={setScenario}
            onFinished={finishRound}
            roundNumber={gameState.roundNumber}
            totalRounds={gameState.totalRounds}
          />
        );
      case GameStage.JUDGING:
        return (
          <ScoringScreen 
            teams={gameState.teams}
            onUpdateScore={updateScore}
            onNextRound={nextRound}
            onEndGame={endGame}
            roundNumber={gameState.roundNumber}
          />
        );
      case GameStage.WINNER:
        return (
          <WinnerScreen 
            teams={gameState.teams}
            onRestart={restartGame}
          />
        );
      default:
        return null;
    }
  };

  return (
    <div className="min-h-screen text-slate-900 font-sans">

      {/* Cartoon Background Elements */}
      <div className="fixed inset-0 z-0 overflow-hidden pointer-events-none opacity-40">
        {/* Big Yellow Blob */}
        <div className="absolute -top-20 -right-20 w-[500px] h-[500px] bg-[#fbbf24] rounded-full border-4 border-black mix-blend-multiply filter blur-sm opacity-50 animate-float"></div>
        {/* Pink Blob */}
        <div className="absolute top-1/2 -left-20 w-[400px] h-[400px] bg-[#f472b6] rounded-full border-4 border-black mix-blend-multiply filter blur-sm opacity-50 animate-float" style={{animationDelay: '1s'}}></div>
        {/* Blue Square */}
        <div className="absolute bottom-0 right-1/4 w-[300px] h-[300px] bg-[#38bdf8] rotate-12 border-4 border-black mix-blend-multiply filter blur-sm opacity-50 animate-float" style={{animationDelay: '2s'}}></div>
      </div>

      {/* Main Content */}
      <main className="relative z-10 min-h-screen flex flex-col">
        {renderStage()}
      </main>
    </div>
  );
};

