          Nyt Scenarie
        </Button>

        <Button 
          variant="secondary" 
          size="xl"
          onClick={() => startTimer(15)} 
          disabled={loading || (timeLeft !== null && timeLeft > 0)}
          className="w-full"
        >
          <Clock className="w-8 h-8" />
          15 Sekunder
        </Button>

        <Button 
          variant="success" 
          size="xl"
          onClick={onFinished} 
          disabled={loading}
          className="w-full"
        >
          <Camera className="w-8 h-8" />
          Se Resultat
        </Button>
      </div>
    </div>
  );
};

