import React, { useEffect, useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Clock, RefreshCw, CheckCircle, Camera, Sparkles } from 'lucide-react';
import { Button } from './Button';
import { generateScenario } from '../services/geminiService';

interface GameScreenProps {
  scenario: string | null;
  setScenario: (scenario: string) => void;
  onFinished: () => void;
  roundNumber: number;
  totalRounds: number;
  onTriggerConfetti: () => void;
}

export const GameScreen: React.FC<GameScreenProps> = ({ 
  scenario, 
  setScenario, 
  onFinished, 
  roundNumber,
  totalRounds,
  onTriggerConfetti
}) => {
  const [loading, setLoading] = useState(false);
  const [timeLeft, setTimeLeft] = useState<number | null>(null);

  const fetchScenario = async () => {
    onTriggerConfetti();
    setLoading(true);
    const newScenario = await generateScenario();
    setScenario(newScenario);
    setLoading(false);
    setTimeLeft(null); 
  };

  useEffect(() => {
    if (!scenario) {
      // Intentionally not triggering confetti on initial load to avoid double burst from previous screen
      const initLoad = async () => {
          setLoading(true);
          const newScenario = await generateScenario();
          setScenario(newScenario);
          setLoading(false);
      }
      initLoad();
    }
  }, []);

  useEffect(() => {
    if (timeLeft === null || timeLeft <= 0) return;
    const timer = setInterval(() => {
      setTimeLeft(prev => (prev !== null ? prev - 1 : null));
    }, 1000);
    return () => clearInterval(timer);
  }, [timeLeft]);

  const startTimer = (seconds: number) => {
    onTriggerConfetti();
    setTimeLeft(seconds);
  };

  const handleFinish = () => {
    onTriggerConfetti();
    onFinished();
  }

  return (
    <div className="flex flex-col items-center justify-center h-full w-full max-w-6xl mx-auto px-4 py-6 font-sans">

      {/* Header Info */}
      <div className="w-full flex justify-between items-center mb-8">
        <div className="bg-white border-4 border-black px-4 py-2 rounded-xl shadow-pop -rotate-2">
          <span className="font-black text-lg">🎬 Runde {roundNumber} af {totalRounds}</span>
        </div>
        <div className="flex space-x-2">
           {[...Array(3)].map((_, i) => (
             <div key={i} className={`w-4 h-4 rounded-full border-2 border-black ${i < (roundNumber % 3) + 1 ? 'bg-yellow-400' : 'bg-white'}`}></div>
           ))}
        </div>
      </div>

      {/* Main Content Area */}
      <div className="flex-grow flex flex-col items-center justify-center w-full mb-8 relative min-h-[400px]">
        <AnimatePresence mode="wait">
          {loading ? (
            <motion.div
              key="loader"
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              className="flex flex-col items-center text-center"
            >
              <div className="w-24 h-24 border-8 border-black border-t-yellow-400 rounded-full animate-spin mb-8"></div>
              <div className="bg-white border-4 border-black p-6 rounded-3xl shadow-pop">
                 <h2 className="text-4xl font-black text-black animate-pulse">
                   Tænker så det knager... 🤔
                 </h2>
              </div>
            </motion.div>
          ) : (
            <motion.div
              key="scenario"
              initial={{ opacity: 0, scale: 0.5, rotate: 10 }}
              animate={{ opacity: 1, scale: 1, rotate: 0 }}
              exit={{ opacity: 0, scale: 1.1 }}
              className="w-full text-center relative max-w-4xl"
            >
               {/* "Action" Starburst behind text */}
               <div className="absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2 w-[600px] h-[600px] bg-yellow-300 rounded-full mix-blend-multiply filter blur-3xl opacity-50 z-0"></div>

              <div className="relative z-10 mb-8 inline-block">
                <div className="bg-black text-white px-6 py-2 rounded-full font-bold text-xl uppercase tracking-widest mb-4 inline-block -rotate-2 border-2 border-white shadow-lg">
                  Opgave:
                </div>

                {/* Comic Speech Bubble */}
                <div className="bg-white border-[6px] border-black p-10 md:p-16 rounded-[60px] shadow-pop relative">
                   <h1 className="text-5xl md:text-7xl font-black text-black leading-tight drop-shadow-sm font-display">
                    "{scenario}"
                   </h1>
                   {/* Little triangle for speech bubble */}
                   <div className="absolute -bottom-8 left-1/2 -translate-x-1/2 w-0 h-0 border-l-[30px] border-l-transparent border-r-[30px] border-r-transparent border-t-[30px] border-t-black"></div>
                   <div className="absolute -bottom-[26px] left-1/2 -translate-x-1/2 w-0 h-0 border-l-[24px] border-l-transparent border-r-[24px] border-r-transparent border-t-[24px] border-t-white"></div>
                </div>
              </div>

              {/* Timer Display */}
              <AnimatePresence>
              {timeLeft !== null && timeLeft > 0 && (
                <motion.div 
                  initial={{ scale: 0, rotate: -180 }}
                  animate={{ scale: 1, rotate: 0 }}
                  exit={{ scale: 0 }}
                  className="mt-8 inline-block"
                >
                  <div className="bg-red-500 text-white font-black text-9xl w-64 h-64 rounded-full border-8 border-black flex items-center justify-center shadow-pop animate-pulse">
                    {timeLeft}
                  </div>
                </motion.div>
              )}

              {timeLeft === 0 && (
                 <motion.div 
                 initial={{ scale: 0.5, opacity: 0 }}
                 animate={{ scale: 1.2, opacity: 1, rotate: [-5, 5, -5, 5, 0] }}
                 exit={{ scale: 0, opacity: 0 }}
                 onClick={() => setTimeLeft(null)}
                 className="fixed inset-0 flex flex-col items-center justify-center z-50 bg-black/60 backdrop-blur-sm cursor-pointer"
               >
                 <div className="bg-yellow-400 border-8 border-black p-12 transform -rotate-6 shadow-[20px_20px_0px_0px_rgba(0,0,0,1)] mb-8">
                    <h1 className="text-9xl font-black text-black uppercase tracking-tighter">FRYS! 🥶</h1>
                 </div>
                 <p className="text-white font-black text-3xl animate-bounce drop-shadow-md bg-black/50 px-6 py-2 rounded-full border-2 border-white">
                   Tryk her for at fortsætte
                 </p>
               </motion.div>
              )}
              </AnimatePresence>
            </motion.div>
          )}
        </AnimatePresence>
      </div>

      {/* Controls */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6 w-full max-w-4xl z-20">
        <Button 
          variant="ghost" 
          onClick={fetchScenario} 
          disabled={loading || (timeLeft !== null && timeLeft > 0)}
          className="w-full bg-white"
        >
          <RefreshCw className="w-6 h-6" />
          Nyt Scenarie
        </Button>

        <Button 
          variant="secondary" 
          size="xl"
          onClick={() => startTimer(15)} 
          disabled={loading || (timeLeft !== null && timeLeft > 0)}
          className="w-full"
        >
          <Clock className="w-8 h-8" />
          15 Sekunder
        </Button>

        <Button 
          variant="success" 
          size="xl"
          onClick={handleFinish} 
          disabled={loading}
          className="w-full"
        >
          <Camera className="w-8 h-8" />
          Se Resultat
        </Button>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { Play, ArrowRight, ArrowLeft, Star, Smile, Zap, Crown } from 'lucide-react';
import { Team } from '../types';
import { Button } from './Button';
import { motion, AnimatePresence } from 'framer-motion';
import { v4 as uuidv4 } from 'uuid';
import ReactConfetti from 'react-confetti';

interface SetupScreenProps {
  onSetupComplete: (teams: Team[], rounds: number) => void;
  onTriggerConfetti: () => void;
}

enum SetupStep {
  WELCOME = 0,
  TEAM_COUNT = 1,
  TEAM_NAMES = 2,
  ROUND_COUNT = 3
}

export const SetupScreen: React.FC<SetupScreenProps> = ({ onSetupComplete, onTriggerConfetti }) => {
  const [step, setStep] = useState<SetupStep>(SetupStep.WELCOME);
  const [teamCount, setTeamCount] = useState<number>(2);
  const [teamNames, setTeamNames] = useState<string[]>(['', '']);
  const [roundCount, setRoundCount] = useState<number>(5);

  const handleStartClick = () => {
    onTriggerConfetti();
    setStep(SetupStep.TEAM_COUNT);
  };

  const handleTeamCountSelect = (count: number) => {
    onTriggerConfetti();
    setTeamCount(count);
    const newNames = Array(count).fill('').map((_, i) => teamNames[i] || '');
    setTeamNames(newNames);
    setStep(SetupStep.TEAM_NAMES);
  };

  const handleNameChange = (index: number, value: string) => {
    const newNames = [...teamNames];
    newNames[index] = value;
    setTeamNames(newNames);
  };

  const handleNamesSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onTriggerConfetti();
    const finalNames = teamNames.map((name, i) => name.trim() || `Hold ${i + 1}`);
    setTeamNames(finalNames);
    setStep(SetupStep.ROUND_COUNT);
  };

  const handleRoundCountSelect = (rounds: number) => {
    onTriggerConfetti();
    setRoundCount(rounds);
    finishSetup(rounds);
  };

  const finishSetup = (rounds: number) => {
    const teams: Team[] = teamNames.map(name => ({
      id: uuidv4(),
      name: name.trim() || "Navnløst Hold",
      score: 0
    }));
    onSetupComplete(teams, rounds);
  };

  const goBack = () => {
    if (step > 0) setStep(step - 1);
  };

  const variants = {
    enter: { opacity: 0, scale: 0.8, rotate: -5 },
    center: { opacity: 1, scale: 1, rotate: 0 },
    exit: { opacity: 0, scale: 1.1, rotate: 5 }
  };

  // Fun helper to give random rotation
  const randRot = () => Math.random() * 6 - 3;

  return (
    <div className="max-w-4xl mx-auto w-full px-4 py-8 flex flex-col h-full justify-center min-h-screen relative font-sans">
      {/* Constant Confetti for Welcome Screen */}
      {step === SetupStep.WELCOME && (
         <div className="fixed inset-0 pointer-events-none">
           <ReactConfetti
             width={window.innerWidth}
             height={window.innerHeight}
             recycle={true} // Constant looping
             numberOfPieces={150}
             gravity={0.1}
             colors={['#8b5cf6', '#f472b6', '#fbbf24', '#38bdf8', '#000000']}
           />
         </div>
      )}

      {step > 0 && (
        <button 
          onClick={goBack}
          className="absolute top-8 left-4 md:left-8 flex items-center bg-white border-2 border-black rounded-full px-4 py-2 font-bold shadow-pop hover:shadow-none hover:translate-x-[2px] hover:translate-y-[2px] transition-all"
        >
          <ArrowLeft className="w-5 h-5 mr-2" />
          Tilbage
        </button>
      )}

      <AnimatePresence mode="wait">

        {/* STEP 0: WELCOME */}
        {step === SetupStep.WELCOME && (
          <motion.div
            key="welcome"
            variants={variants}
            initial="enter"
            animate="center"
            exit="exit"
            className="text-center flex flex-col items-center"
          >
            <div className="relative mb-8">
               <div className="absolute inset-0 bg-yellow-400 rounded-full animate-ping opacity-20"></div>
               <div className="relative bg-white border-4 border-black p-8 rounded-full shadow-pop rotate-3">
                 <Smile className="w-24 h-24 text-purple-600" strokeWidth={2.5} />
               </div>
            </div>

            <h1 className="text-7xl md:text-9xl font-black text-black mb-12 drop-shadow-md tracking-tighter"
                style={{ WebkitTextStroke: '2px white' }}>
              Sæt Scenen!
            </h1>

            <Button 
              onClick={handleStartClick} 
              size="xl" 
              variant="success"
              wiggle={true}
              className="min-w-[300px] text-3xl"
            >
              Start Spillet!
              <Play className="w-8 h-8 ml-2 fill-current" />
            </Button>
          </motion.div>
        )}

        {/* STEP 1: TEAM COUNT */}
        {step === SetupStep.TEAM_COUNT && (
          <motion.div
            key="count"
            variants={variants}
            initial="enter"
            animate="center"
            exit="exit"
            className="w-full max-w-3xl mx-auto text-center"
          >
            <div className="bg-white border-4 border-black rounded-3xl p-8 shadow-pop mb-12 inline-block -rotate-1">
               <h2 className="text-4xl font-black text-black mb-2">Hvor mange hold er I? 🔢</h2>
               <p className="text-xl font-hand font-bold text-slate-500">I skal være ca. 4-6 elever på hvert hold.</p>
            </div>

            <div className="grid grid-cols-2 md:grid-cols-3 gap-6">
              {[2, 3, 4, 5, 6, 7].map((num) => (
                <motion.button
                  key={num}
                  whileHover={{ scale: 1.05, rotate: randRot() }}
                  whileTap={{ scale: 0.95 }}
                  onClick={() => handleTeamCountSelect(num)}
                  className="bg-white border-4 border-black rounded-3xl p-6 shadow-pop hover:bg-sky-100 flex flex-col items-center justify-center min-h-[160px]"
                >
                  <span className="text-7xl font-black text-primary mb-2 drop-shadow-sm">{num}</span>
                  <span className="text-black font-bold uppercase tracking-wider text-lg bg-yellow-300 px-3 py-1 rounded-full border-2 border-black">Hold</span>
                </motion.button>
              ))}
            </div>
          </motion.div>
        )}

        {/* STEP 2: TEAM NAMES */}
        {step === SetupStep.TEAM_NAMES && (
          <motion.div
            key="names"
            variants={variants}
            initial="enter"
            animate="center"
            exit="exit"
            className="w-full max-w-3xl mx-auto"
          >
             <div className="text-center mb-8">
                <div className="bg-white border-4 border-black rounded-3xl p-6 shadow-pop inline-block rotate-2">
                   <h2 className="text-4xl font-black text-black">Navngiv Holdene! 🏷️</h2>
                </div>
             </div>

            <form onSubmit={handleNamesSubmit} className="space-y-6 mb-8">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                {teamNames.map((name, index) => (
                  <motion.div 
                    key={index} 
                    className="relative"
                    initial={{ x: -20, opacity: 0 }}
                    animate={{ x: 0, opacity: 1 }}
                    transition={{ delay: index * 0.1 }}
                  >
                    <div className="absolute -left-3 -top-3 w-10 h-10 rounded-full bg-yellow-400 border-4 border-black flex items-center justify-center font-black text-lg z-10 shadow-sm">
                      {index + 1}
                    </div>
                    <input
                      type="text"
                      value={name}
                      onChange={(e) => handleNameChange(index, e.target.value)}
                      placeholder={`Holdnavn ${index + 1}...`}
                      autoFocus={index === 0}
                      className="w-full pl-10 pr-4 py-5 text-2xl font-bold font-hand bg-white border-4 border-black rounded-2xl focus:bg-yellow-50 focus:shadow-pop-hover outline-none transition-all placeholder:text-slate-300 text-black shadow-pop"
                    />
                  </motion.div>
                ))}
              </div>

              <div className="flex justify-center mt-12">
                <Button type="submit" size="xl" variant="accent" wiggle className="shadow-pop">
                  Så kører vi!
                  <ArrowRight className="w-8 h-8 ml-2" />
                </Button>
              </div>
            </form>
          </motion.div>
        )}

        {/* STEP 3: ROUND COUNT */}
        {step === SetupStep.ROUND_COUNT && (
          <motion.div
             key="rounds"
             variants={variants}
             initial="enter"
             animate="center"
             exit="exit"
             className="w-full max-w-3xl mx-auto text-center"
           >
             <div className="mb-10">
                <div className="bg-white border-4 border-black rounded-3xl p-6 shadow-pop inline-block -rotate-1">
                   <h2 className="text-4xl font-black text-black">Hvor længe skal vi lege? ⏱️</h2>
                </div>
             </div>

             <div className="grid grid-cols-2 gap-6 max-w-2xl mx-auto">
               {[
                 { count: 3, label: "Lyn-runde", desc: "⚡ Hurtig pause", color: "bg-green-100", icon: <Zap className="w-8 h-8" /> },
                 { count: 5, label: "Standard", desc: "👍 Helt perfekt", color: "bg-blue-100", icon: <Smile className="w-8 h-8" /> },
                 { count: 8, label: "Lang leg", desc: "⭐ God tid", color: "bg-purple-100", icon: <Star className="w-8 h-8" /> },
                 { count: 12, label: "Marathon", desc: "👑 Det store show", color: "bg-orange-100", icon: <Crown className="w-8 h-8" /> }
               ].map((opt) => (
                 <motion.button
                   key={opt.count}
                   whileHover={{ scale: 1.05, rotate: randRot() }}
                   whileTap={{ scale: 0.95 }}
                   onClick={() => handleRoundCountSelect(opt.count)}
                   className={`relative border-4 border-black rounded-3xl p-6 shadow-pop hover:shadow-pop-hover flex flex-col items-center justify-center text-left ${opt.color}`}
                 >
                   <div className="absolute top-4 right-4 text-black opacity-50">{opt.icon}</div>
                   <span className="text-6xl font-black mb-2 text-black">{opt.count}</span>
                   <span className="font-black text-xl uppercase tracking-tight">{opt.label}</span>
                   <span className="text-sm font-hand font-bold mt-1 text-slate-700">{opt.desc}</span>
                 </motion.button>
               ))}
             </div>
           </motion.div>
        )}

      </AnimatePresence>
    </div>
  );
};

import React, { useEffect, useState } from 'react';
