import React, { useState } from 'react';
import { v4 as uuidv4 } from 'uuid';
import ReactConfetti from 'react-confetti';
import { Team, GameState, GameStage } from './types';
import { SetupScreen } from './components/SetupScreen';
import { GameScreen } from './components/GameScreen';
import { ScoringScreen } from './components/ScoringScreen';
import { WinnerScreen } from './components/WinnerScreen';

const App: React.FC = () => {
  const [gameState, setGameState] = useState<GameState>({
    stage: GameStage.SETUP,
    teams: [],
    currentScenario: null,
    history: [],
    roundNumber: 1,
    totalRounds: 5,
    roundDuration: 120 // Default 2 minutes
  });

  // Global Burst State
  const [burstKey, setBurstKey] = useState(0);

  const triggerConfetti = () => {
    setBurstKey(prev => prev + 1);
  };

  const handleSetupComplete = (teams: Team[], rounds: number, duration: number) => {
    setGameState(prev => ({
      ...prev,
      teams: teams,
      totalRounds: rounds,
      roundDuration: duration,
      stage: GameStage.SCENARIO,
      roundNumber: 1,
      currentScenario: null
    }));
  };

  const setScenario = (scenario: string) => {
    setGameState(prev => ({
      ...prev,
      currentScenario: scenario,
      history: [...prev.history, scenario]
    }));
  };

  const finishRound = () => {
    setGameState(prev => ({
      ...prev,
      stage: GameStage.JUDGING
    }));
  };

  const updateScore = (teamId: string, points: number) => {
    setGameState(prev => ({
      ...prev,
      teams: prev.teams.map(t => 
        t.id === teamId ? { ...t, score: t.score + points } : t
      )
    }));
  };

  const nextRound = () => {
    if (gameState.roundNumber >= gameState.totalRounds) {
      endGame();
    } else {
      setGameState(prev => ({
        ...prev,
        stage: GameStage.SCENARIO,
        currentScenario: null,
        roundNumber: prev.roundNumber + 1
      }));
    }
  };

  const endGame = () => {
    setGameState(prev => ({
      ...prev,
      stage: GameStage.WINNER
    }));
  };

  const restartGame = () => {
    setGameState({
      stage: GameStage.SETUP,
      teams: [],
      currentScenario: null,
      history: [],
      roundNumber: 1,
      totalRounds: 5,
      roundDuration: 120
    });
  };

  // Simple render switch
  const renderStage = () => {
    switch (gameState.stage) {
      case GameStage.SETUP:
        return (
          <SetupScreen 
            onSetupComplete={handleSetupComplete}
            onTriggerConfetti={triggerConfetti}
          />
        );
      case GameStage.SCENARIO:
        return (
          <GameScreen 
            scenario={gameState.currentScenario}
            setScenario={setScenario}
            onFinished={finishRound}
            roundNumber={gameState.roundNumber}
            totalRounds={gameState.totalRounds}
            roundDuration={gameState.roundDuration}
            onTriggerConfetti={triggerConfetti}
            onBack={restartGame}
          />
        );
      case GameStage.JUDGING:
        return (
          <ScoringScreen 
            teams={gameState.teams}
            onUpdateScore={updateScore}
            onNextRound={nextRound}
            onEndGame={endGame}
            roundNumber={gameState.roundNumber}
            onTriggerConfetti={triggerConfetti}
            onBack={restartGame}
          />
        );
      case GameStage.WINNER:
        return (
          <WinnerScreen 
            teams={gameState.teams}
            onRestart={restartGame}
            onTriggerConfetti={triggerConfetti}
          />
        );
      default:
        return null;
    }
  };

  return (
    <div className="min-h-screen text-slate-900 font-sans relative">

      {/* Global Burst Confetti */}
      {burstKey > 0 && (
        <div className="fixed inset-0 pointer-events-none z-[100]">
          <ReactConfetti
            key={burstKey}
            width={window.innerWidth}
            height={window.innerHeight}
            recycle={false}
            numberOfPieces={300}
            gravity={0.3}
            initialVelocityY={20}
            colors={['#8b5cf6', '#f472b6', '#fbbf24', '#38bdf8', '#000000']}
          />
        </div>
      )}

      {/* Cartoon Background Elements */}
      <div className="fixed inset-0 z-0 overflow-hidden pointer-events-none opacity-40">
        {/* Big Yellow Blob */}
        <div className="absolute -top-20 -right-20 w-[500px] h-[500px] bg-[#fbbf24] rounded-full border-4 border-black mix-blend-multiply filter blur-sm opacity-50 animate-float"></div>
        {/* Pink Blob */}
        <div className="absolute top-1/2 -left-20 w-[400px] h-[400px] bg-[#f472b6] rounded-full border-4 border-black mix-blend-multiply filter blur-sm opacity-50 animate-float" style={{animationDelay: '1s'}}></div>
        {/* Blue Square */}
        <div className="absolute bottom-0 right-1/4 w-[300px] h-[300px] bg-[#38bdf8] rotate-12 border-4 border-black mix-blend-multiply filter blur-sm opacity-50 animate-float" style={{animationDelay: '2s'}}></div>
      </div>

      {/* Main Content */}
      <main className="relative z-10 min-h-screen flex flex-col">
        {renderStage()}
      </main>
    </div>
  );
};

export default App;

import React, { useEffect, useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Clock, RefreshCw, CheckCircle, Camera, Sparkles, LogOut, Pause, Play, Plus } from 'lucide-react';
import { Button } from './Button';
import { generateScenario } from '../services/geminiService';

interface GameScreenProps {
  scenario: string | null;
  setScenario: (scenario: string) => void;
  onFinished: () => void;
  roundNumber: number;
  totalRounds: number;
  roundDuration: number;
  onTriggerConfetti: () => void;
  onBack: () => void;
}

export const GameScreen: React.FC<GameScreenProps> = ({ 
  scenario, 
  setScenario, 
  onFinished, 
  roundNumber,
  totalRounds,
  roundDuration,
  onTriggerConfetti,
  onBack
}) => {
  const [loading, setLoading] = useState(false);
  const [timeLeft, setTimeLeft] = useState<number | null>(null);
  const [isPaused, setIsPaused] = useState(false);

  const fetchScenario = async () => {
    onTriggerConfetti();
    setLoading(true);
    const newScenario = await generateScenario();
    setScenario(newScenario);
    setLoading(false);
    setTimeLeft(roundDuration); // Auto start timer based on config
    setIsPaused(false);
  };

  useEffect(() => {
    // Initial load logic
    if (!scenario) {
      const initLoad = async () => {
          setLoading(true);
          const newScenario = await generateScenario();
          setScenario(newScenario);
          setLoading(false);
          setTimeLeft(roundDuration); 
          setIsPaused(false);
      }
      initLoad();
    } else if (timeLeft === null) {
      // If returning to screen with scenario but no timer (rare case), restart it
      setTimeLeft(roundDuration);
      setIsPaused(false);
    }
  }, []);

  useEffect(() => {
    if (timeLeft === null || timeLeft <= 0 || isPaused) return;
    const timer = setInterval(() => {
      setTimeLeft(prev => (prev !== null ? prev - 1 : null));
    }, 1000);
    return () => clearInterval(timer);
  }, [timeLeft, isPaused]);

  const handleFinish = () => {
    onTriggerConfetti();
    onFinished();
  }

  const togglePause = () => {
    if (timeLeft !== null && timeLeft > 0) {
      setIsPaused(!isPaused);
    }
  }

  const addTime = () => {
    setTimeLeft(prev => (prev !== null ? prev + 30 : 30));
    setIsPaused(false);
  };

  // Helper to format time as MM:SS if > 60, otherwise just SS
  const formatTime = (seconds: number) => {
    const m = Math.floor(seconds / 60);
    const s = seconds % 60;
    if (m > 0) {
        return `${m}:${s < 10 ? '0' : ''}${s}`;
    }
    return s;
  };

  return (
    <div className="flex flex-col items-center justify-center h-full w-full max-w-6xl mx-auto px-4 py-6 font-sans relative">

      {/* Top Navigation Bar */}
      <div className="w-full flex flex-wrap justify-between items-center mb-4 gap-4">
        <div className="flex items-center gap-4">
          <button 
            onClick={onBack}
            className="bg-white border-2 border-black rounded-full px-4 py-2 font-bold shadow-pop hover:shadow-none hover:translate-x-[2px] hover:translate-y-[2px] transition-all flex items-center gap-2 text-sm"
          >
            <LogOut className="w-4 h-4" />
            Afslut
          </button>

          <div className="bg-white border-4 border-black px-4 py-2 rounded-xl shadow-pop -rotate-2">
            <span className="font-black text-lg">🎬 Runde {roundNumber}/{totalRounds}</span>
          </div>
        </div>

        <div className="flex space-x-2 hidden sm:flex">
           {[...Array(3)].map((_, i) => (
             <div key={i} className={`w-4 h-4 rounded-full border-2 border-black ${i < (roundNumber % 3) + 1 ? 'bg-yellow-400' : 'bg-white'}`}></div>
           ))}
        </div>
      </div>

      {/* Main Content Area */}
      <div className="flex-grow flex flex-col items-center justify-center w-full mb-8 relative min-h-[400px]">
        <AnimatePresence mode="wait">
          {loading ? (
            <motion.div
              key="loader"
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              className="flex flex-col items-center text-center"
            >
              <div className="w-24 h-24 border-8 border-black border-t-yellow-400 rounded-full animate-spin mb-8"></div>
              <div className="bg-white border-4 border-black p-6 rounded-3xl shadow-pop">
                 <h2 className="text-4xl font-black text-black animate-pulse">
                   Tænker så det knager... 🤔
                 </h2>
              </div>
            </motion.div>
          ) : (
            <motion.div
              key="scenario"
              initial={{ opacity: 0, scale: 0.5, rotate: 10 }}
              animate={{ opacity: 1, scale: 1, rotate: 0 }}
              exit={{ opacity: 0, scale: 1.1 }}
              className="w-full text-center relative max-w-4xl"
            >
               {/* "Action" Starburst behind text */}
               <div className="absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2 w-[600px] h-[600px] bg-yellow-300 rounded-full mix-blend-multiply filter blur-3xl opacity-50 z-0"></div>

              <div className="relative z-10 mb-8 inline-block">
                <div className="bg-black text-white px-6 py-2 rounded-full font-bold text-xl uppercase tracking-widest mb-4 inline-block -rotate-2 border-2 border-white shadow-lg">
                  Opgave:
                </div>

                {/* Comic Speech Bubble */}
                <div className="bg-white border-[6px] border-black p-10 md:p-16 rounded-[60px] shadow-pop relative">
                   <h1 className="text-5xl md:text-7xl font-black text-black leading-tight drop-shadow-sm font-display">
                    "{scenario}"
                   </h1>
                   {/* Little triangle for speech bubble */}
                   <div className="absolute -bottom-8 left-1/2 -translate-x-1/2 w-0 h-0 border-l-[30px] border-l-transparent border-r-[30px] border-r-transparent border-t-[30px] border-t-black"></div>
                   <div className="absolute -bottom-[26px] left-1/2 -translate-x-1/2 w-0 h-0 border-l-[24px] border-l-transparent border-r-[24px] border-r-transparent border-t-[24px] border-t-white"></div>
                </div>
              </div>

              {/* Timer Display */}
              <AnimatePresence>
              {timeLeft !== null && timeLeft > 0 && (
                <div className="flex items-center justify-center gap-4 mt-8 flex-col sm:flex-row relative z-20">
                    <motion.button 
                      initial={{ scale: 0, rotate: -180 }}
                      animate={{ scale: 1, rotate: 0 }}
                      exit={{ scale: 0 }}
                      onClick={togglePause}
                      whileHover={{ scale: 1.05 }}
                      whileTap={{ scale: 0.95 }}
                      className={`relative text-white font-black text-7xl md:text-8xl w-64 h-64 rounded-full border-8 border-black flex flex-col items-center justify-center shadow-pop cursor-pointer hover:shadow-pop-hover transition-all ${isPaused ? 'bg-slate-400' : timeLeft <= 10 ? 'bg-red-600 animate-pulse' : 'bg-red-500'}`}
                    >
                        <span>{formatTime(timeLeft)}</span>
                        <span className="text-xl uppercase tracking-widest mt-2 opacity-80 flex items-center gap-2">
                           {isPaused ? <Play className="w-5 h-5 fill-current" /> : <Pause className="w-5 h-5 fill-current" />}
                           {isPaused ? "Start" : "Pause"}
                        </span>
                    </motion.button>

                    <motion.button
                       whileHover={{ scale: 1.1, rotate: 5 }}
                       whileTap={{ scale: 0.9 }}
                       onClick={addTime}
                       className="bg-blue-400 text-white w-20 h-20 rounded-full border-4 border-black flex items-center justify-center shadow-pop hover:bg-blue-500"
                       title="Læg 30 sekunder til"
                    >
                       <span className="font-black text-xl flex flex-col items-center leading-none">
                         <Plus className="w-6 h-6" />
                         30s
                       </span>
                    </motion.button>
                </div>
              )}

              {timeLeft === 0 && (
                 <motion.div 
                 initial={{ scale: 0.5, opacity: 0 }}
                 animate={{ scale: 1.2, opacity: 1, rotate: [-5, 5, -5, 5, 0] }}
                 exit={{ scale: 0, opacity: 0 }}
                 className="fixed inset-0 flex flex-col items-center justify-center z-50 bg-black/60 backdrop-blur-sm cursor-pointer"
                 onClick={() => setTimeLeft(null)}
               >
                 <div className="bg-yellow-400 border-8 border-black p-12 transform -rotate-6 shadow-[20px_20px_0px_0px_rgba(0,0,0,1)] mb-8">
                    <h1 className="text-9xl font-black text-black uppercase tracking-tighter">FRYS! 🥶</h1>
                 </div>

                 <div className="flex flex-col gap-4">
                    <p className="text-white font-black text-3xl animate-bounce drop-shadow-md bg-black/50 px-6 py-2 rounded-full border-2 border-white text-center">
                    Tryk her for at fortsætte
                    </p>
                    <button 
                        onClick={(e) => { e.stopPropagation(); addTime(); }}
                        className="bg-blue-500 hover:bg-blue-600 text-white font-black py-3 px-6 rounded-xl border-4 border-white shadow-lg mx-auto flex items-center gap-2"
                    >
                        <Plus className="w-6 h-6" /> Giv mere tid
                    </button>
                 </div>
               </motion.div>
              )}
              </AnimatePresence>
            </motion.div>
          )}
        </AnimatePresence>
      </div>

      {/* Controls */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6 w-full max-w-3xl z-20">
        <Button 
          variant="ghost" 
          onClick={fetchScenario} 
          disabled={loading || (timeLeft !== null && timeLeft > 0)}
          className="w-full bg-white"
        >
          <RefreshCw className="w-6 h-6" />
          Nyt Scenarie
        </Button>

        <Button 
          variant="success" 
          size="xl"
          onClick={handleFinish} 
          disabled={loading}
          className="w-full"
        >
          <Camera className="w-8 h-8" />
          Se Resultat
        </Button>
      </div>
    </div>
  );
};

import React, { useEffect, useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Clock, RefreshCw, CheckCircle, Camera, Sparkles, LogOut, Pause, Play, Plus } from 'lucide-react';
import { Button } from './Button';
import { generateScenario } from '../services/geminiService';

interface GameScreenProps {
  scenario: string | null;
  setScenario: (scenario: string) => void;
  onFinished: () => void;
  roundNumber: number;
  totalRounds: number;
  roundDuration: number;
  onTriggerConfetti: () => void;
  onBack: () => void;
}

export const GameScreen: React.FC<GameScreenProps> = ({ 
  scenario, 
  setScenario, 
  onFinished, 
  roundNumber,
  totalRounds,
  roundDuration,
  onTriggerConfetti,
  onBack
}) => {
