  teams, 
  onUpdateScore, 
  onNextRound, 
  onEndGame,
  roundNumber,
  onTriggerConfetti,
  onBack
}) => {

  const handleScore = (teamId: string, points: number) => {
    onTriggerConfetti();
    onUpdateScore(teamId, points);
  }

  const handleNext = () => {
    onTriggerConfetti();
    onNextRound();
  }

  const handleEnd = () => {
    onTriggerConfetti();
    onEndGame();
  }

  // Determine layout density based on team count
  const teamCount = teams.length;
  const isCompact = teamCount > 3;
  const isVeryCompact = teamCount > 6;

