    if (teamCount <= 2) return "grid-cols-1 md:grid-cols-2";
    if (teamCount === 3) return "grid-cols-1 md:grid-cols-3";
    if (teamCount === 4) return "grid-cols-2";
    if (teamCount <= 6) return "grid-cols-2 md:grid-cols-3";
    return "grid-cols-3 md:grid-cols-4";
  };

  // Dynamic Styles
  const cardPadding = isCompact ? "p-3" : "p-6";
  const titleSize = isCompact ? "text-xl md:text-2xl" : "text-3xl md:text-4xl";
  const buttonPadding = isCompact ? "py-2 md:py-3" : "py-4";
