               <div className="w-full flex items-center justify-between mb-2 border-b-2 border-slate-100 pb-2">
                  <div className={`rounded-full bg-yellow-400 border-2 border-black flex items-center justify-center font-black ${isCompact ? 'w-8 h-8 text-sm' : 'w-10 h-10 text-lg'}`}>
                     {index + 1}
