                  >
                     <span className={buttonText}>+5</span>
                     <span className={buttonSubText}>Episk</span>
                  </button>
               </div>
            </motion.div>
          ))}
        </div>
      </div>

      {/* Footer Controls */}
      <div className="flex-shrink-0 mt-2 mb-2 flex flex-row justify-center gap-4 items-center z-20">
