interface ScoringScreenProps {
  teams: Team[];
  onUpdateScore: (teamId: string, points: number) => void;
  onNextRound: () => void;
  onEndGame: () => void;
  roundNumber: number;
  onTriggerConfetti: () => void;
  onBack: () => void;
}

