  const teamCount = teams.length;
  // We only consider it "compact" if we really have a lot of teams (8+), otherwise fill space!
  const isCompact = teamCount > 8;

  // Dynamic Grid Layout Generator
  // We explicitly define rows to force the grid to fill the vertical height
  const getGridClass = () => {
    // Mobile defaults (vertical scrolling often needed on mobile if many teams, but we try to fit)
    const mobile = teamCount <= 3 ? "grid-cols-1" : "grid-cols-2";

    // Desktop Logic (md and up) - Aim to fill the rectangle
    if (teamCount <= 2) return `${mobile} md:grid-cols-2 md:grid-rows-1`;
    if (teamCount === 3) return `${mobile} md:grid-cols-3 md:grid-rows-1`;
    if (teamCount === 4) return "grid-cols-2 grid-rows-2"; // 2x2
    if (teamCount <= 6) return "grid-cols-2 md:grid-cols-3 md:grid-rows-2"; // 2x3
    if (teamCount <= 8) return "grid-cols-2 md:grid-cols-4 md:grid-rows-2"; // 2x4
