        >
          <LogOut className="w-3 h-3 md:w-4 md:h-4" />
          Afslut
        </button>

         <div className="bg-white border-2 border-black px-4 py-1 rounded-xl shadow-pop -rotate-1 hidden md:block">
          <span className="font-bold text-sm uppercase tracking-widest text-slate-500 mr-2">Runde {roundNumber}</span>
          <span className="font-black text-lg text-black">Giv Point 🏆</span>
        </div>

        {/* Placeholder for balance on desktop */}
        <div className="w-20 hidden md:block"></div>
      </div>

      {/* Main Grid Area - Flex Grow to take available space */}
      <div className="flex-grow flex flex-col w-full min-h-0 relative z-10 py-1">
