              className={`bg-white rounded-2xl border-4 border-black ${cardPadding} shadow-pop flex flex-col justify-between items-center relative overflow-hidden h-full`}
            >
               {/* Header - Rank & Score */}
               <div className="w-full flex items-center justify-between mb-1 border-b-2 border-slate-100 pb-1 flex-shrink-0">
                  <div className={`rounded-full bg-yellow-400 border-2 border-black flex items-center justify-center font-black ${teamCount > 6 ? 'w-8 h-8 text-sm' : 'w-10 h-10 md:w-12 md:h-12 text-lg md:text-xl'}`}>
                     {index + 1}
                  </div>
                  <div className="flex items-center gap-2 bg-black text-white px-3 py-1 rounded-lg">
                     <Star className="w-4 h-4 md:w-5 md:h-5 fill-current" />
                     <span className={`font-bold ${teamCount > 6 ? 'text-sm' : 'text-lg md:text-xl'}`}>{team.score}</span>
                  </div>
               </div>

